+{"connection_id":"BC-ae524622b69c1537d2cd","ref":"SBLGNT:Matt.13.13","status":"rejected","reason":"Seeing without seeing and hearing without understanding duplicates Isaiah's original formula included at ¶25.","paragraphs":[],"evidence":["SBLGNT:Matt.13.13"],"annotations":[]}
+{"connection_id":"BC-0735e3aa0607f8760b26","ref":"SBLGNT:Matt.13.14","status":"rejected","reason":"Matthew explicitly quotes Isa 6:9; the Isaiah verse is already the selected primary witness for failed perception.","paragraphs":[],"evidence":["SBLGNT:Matt.13.14"],"annotations":[]}
+{"connection_id":"BC-c4d1710d1a523663812c","ref":"SBLGNT:Matt.13.15","status":"rejected","reason":"Closed eyes and possible turning reproduce Isa 6:10, which is cited directly at ¶25.","paragraphs":[],"evidence":["SBLGNT:Matt.13.15"],"annotations":[]}
